}

showChildrenEvent = (event, targetDiv) => {
  if (event.target === targetDiv) {
    const showChildren = event.target.getAttribute("showchildren");
    if (showChildren == "true") {
      Array.from(event.target.children).forEach(child => {
        child.style.display = "none";
        event.target.setAttribute("showchildren", "false");
      })
    }
    else {
      Array.from(event.target.children).forEach(child => {
        child.style.display = "";
        event.target.setAttribute("showchildren", "true");
      })
    }
  }
}

createHTML = (className, root, section, depth, eventFunction) => {
  const newDiv = document.createElement("div");
  newDiv.style.marginLeft = `${depth / 3}vw`;
  newDiv.style.marginRight = "0px";
  if (depth != 0) {
    newDiv.style.display = 'none';
    newDiv.style.fontWeight = 300;
  }
  else {
    newDiv.style.fontWeight = 600;
  }
  newDiv.className = className;
  newDiv.setAttribute('showChildren', 'false');
  newDiv.id = `${root.id}-${section}`;
  newDiv.addEventListener('click', (event) => { eventFunction(event, newDiv) });
  newDiv.textContent = section;
  root.appendChild(newDiv);
  const sectionHTML = document.getElementById(`${root.id}-${section}`);
  return sectionHTML;
}

getChannels = (sections, trace, rootHTML, depth) => {

  sections.map(section => {
    const sectionHTML = createHTML("section", rootHTML, section["name"], depth, showChildrenEvent);

    if ("channels" in section && section["channels"].length > 0) {
      const sectionWithChannels = section["channels"];
      sectionWithChannels.map(channel => {
        const newDiv = createHTML("section", sectionHTML, channel["name"], depth, showChildrenEvent)
        const codes = channel["codes"]
        codes.map(code => {
          createHTML("leaf", newDiv, code, depth, appendChildEvent)
        })
      })
    }

    if ("sections" in section && section["sections"].length > 0) {
      section["sections"].map(subsection => {
        getChannels([subsection], `${trace}-${subsection["name"]}`, sectionHTML, depth + 1)
      })
    }
  })

}


