  }
}

setRelativetime = (button) => {
  const relativeTimerange = button.getAttribute("relhours");

  if (relativeTimerange == 0) {
    const nowDate = new Date();

    const today = new Date(nowDate.setHours(8, 0, 0, 0));

    const yesterdayDate = new Date(nowDate.setDate(nowDate.getDate() - 1));
    const yesterday = new Date(yesterdayDate.setHours(20, 0, 0, 0));

    dateTimeTo.value = formatDate(today);
    dateTimeFrom.value = formatDate(yesterday);

  }
  else {
    const nowDate = new Date();
    dateTimeTo.value = formatDate(nowDate);
    const fromRelative = new Date(nowDate - relativeTimerange * 60 * 60 * 1000);
    dateTimeFrom.value = formatDate(fromRelative);
  }
}


