downloadCSV = () => {
  let data = context.data;
  let headers = "";
  keys = Object.keys(data[0]);
  for (let key of keys) {
    if (key != "statusColor") {
      headers += key;
      headers += ","
    }
  }
  let values = "";
  data.map(row => {
    for (let key of keys) {
      if (key != "statusColor") {
        if (key == "Timestamp") {
          const datetime = new Date(row[key]);
          values += datetime.toISOString();
        }
        else {
          if (row[key] == undefined) {
            values += "0"
          }
          else {
            values += row[key];
          }
        }
        values += ","
      }
    }
    values += '\n';
  })
  const csv = `${headers}
${values}`;
  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = "data.csv";
  link.click();
  URL.revokeObjectURL(url);
}

