const allSystems = context.grafana.replaceVariables("${aux_logs_subsystems:csv}");
const systemSelector = document.getElementById("systemSelector");
const selectedSystems = context.grafana.replaceVariables("${logs_subsystem:text}");

if (systemSelector != null) {
  const systemList = allSystems.split(",");
  systemSelector.innerHTML = "";
  systemList.map(system => {
    const containerDiv = document.createElement('div');
    containerDiv.className = "logsSystemContainer";
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.value = system;
    checkbox.name = 'system';
    const label = document.createElement('label');
    label.className = "logsSystemLabel";
    label.textContent = system;
    if (selectedSystems.includes(system)) {
      checkbox.checked = true;
    }
    containerDiv.appendChild(checkbox);
    containerDiv.appendChild(label);
    systemSelector.appendChild(containerDiv);
  })

  const checkboxes = document.querySelectorAll('input[name="system"]');
  checkboxes.forEach(checkbox => {
    checkbox.addEventListener('change', () => {
      console.log(checkboxes)
      selectedList = [];
      Array.from(checkboxes).map(checkbox => {
        subsystem = checkbox.value;
        if (checkbox.checked == true && !selectedList.includes(subsystem)) {
          selectedList.push(subsystem);
        }
      })
      console.log(selectedList);
      context.grafana.locationService.partial(
        {
          'var-logs_subsystem': selectedList.map(selected => `subsystem:${selected} `).join(" "),
        },
        true
      )

    });
  });
}

const input = document.getElementById("searchMsgInput");
const auxMsg = context.grafana.replaceVariables("${aux_search_message:text}");

input.value = auxMsg;

searchMsg = () => {
  const input = document.getElementById("searchMsgInput").value;
  const inputList = input.split(" ");

  let stringToSearch = ""
  if (input == "") {
    stringToSearch = "msg:**"
  }
  else {
    for (let element of inputList) {
      if (["AND", "OR", "NOT", "(", ")"].some(logicOperator => element.includes(logicOperator))) {
        stringToSearch += element;
      }
      else {
        stringToSearch += `msg:*${element}*`
      }
      stringToSearch += " ";
    }
  }


  context.grafana.locationService.partial(
    {
      'var-search_message': stringToSearch,
    },
    true
  )
  context.grafana.locationService.partial(
    {
      'var-aux_search_message': input,
    },
    true
  )
};


document.getElementById('searchMsgInput').addEventListener('keydown', function (event) {
  if (event.key === 'Enter') {
    event.preventDefault();
    searchMsg();
  }
});

