const formatOptions = {
  year: 'numeric',
  month: 'numeric',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  fractionalSecondDigits: 3,
  hourCycle: 'h23',
  timeZone: context.panelData.request.timezone != 'browser' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone
};

context.handlebars.registerHelper('changeTime', function (timestamp) {
  const date = new Date(timestamp);
  const formattedTime = date.toLocaleString('en-US', formatOptions);
  const [datePart, timePart] = formattedTime.split(', ');
  const [month, day, year] = datePart.split('/');
  const [hours, minutes, seconds] = timePart.split(':');
  const [second, fraction] = seconds.split('.');
  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;
});

